#!/bin/bash
fail=0
t=$(mktemp); printf '# h\naoi\t2026-01-01\t10:00\t11:00\tx\nkaede\t2026-01-01\t09:00\t10:00\ty\n' > "$t"
[ "$(BOOKINGS=$t bash src/list.sh --room aoi)" = '2026-01-01 10:00-11:00 aoi x' ] || { echo "list --room"; fail=1; }
[ "$(BOOKINGS=$t bash src/list.sh | head -1)" = '2026-01-01 09:00-10:00 kaede y' ] || { echo "list unchanged"; fail=1; }
[ -z "$(BOOKINGS=$t bash src/list.sh --room ao)" ] || { echo "list --room matched a prefix"; fail=1; }
# --room と日付を一緒に渡す（Issue #91）
[ "$(BOOKINGS=$t bash src/list.sh --room aoi 2026-01-01)" = '2026-01-01 10:00-11:00 aoi x' ] || { echo "list --room with date"; fail=1; }
[ -z "$(BOOKINGS=$t bash src/list.sh --room aoi 2026-01-02)" ] || { echo "list --room with other date"; fail=1; }
# --room に値が無いときは exit 2 と usage
out=$(BOOKINGS=$t bash src/list.sh --room 2>/tmp/list_room_err.$$); code=$?
[ "$code" = 2 ] && [ -z "$out" ] && [ "$(cat /tmp/list_room_err.$$)" = 'usage: list.sh [--room ROOM] [DATE]' ] || { echo "list --room without value"; fail=1; }
# 日付の形式が違うときは exit 2 と bad date
out=$(BOOKINGS=$t bash src/list.sh 2026/11/10 2>/tmp/list_room_err.$$); code=$?
[ "$code" = 2 ] && [ -z "$out" ] && [ "$(cat /tmp/list_room_err.$$)" = 'bad date: 2026/11/10 (expected YYYY-MM-DD)' ] || { echo "list bad date format"; fail=1; }
# 月・日の範囲が外れているときも exit 2 と bad date
out=$(BOOKINGS=$t bash src/list.sh 2026-13-01 2>/tmp/list_room_err.$$); code=$?
[ "$code" = 2 ] && [ -z "$out" ] && [ "$(cat /tmp/list_room_err.$$)" = 'bad date: 2026-13-01 (expected YYYY-MM-DD)' ] || { echo "list bad month"; fail=1; }
out=$(BOOKINGS=$t bash src/list.sh --room aoi 2026-01-32 2>/tmp/list_room_err.$$); code=$?
[ "$code" = 2 ] && [ -z "$out" ] && [ "$(cat /tmp/list_room_err.$$)" = 'bad date: 2026-01-32 (expected YYYY-MM-DD)' ] || { echo "list bad day"; fail=1; }
rm -f "$t" /tmp/list_room_err.$$; exit $fail

